   Valor do fundo: '' (padrão), '#rrggbb' (cor), 'https://…' (foto por link) ou 'data:image/…' (foto enviada, só no navegador) */
const FUNDOS=[['Azul claro','#DCE8F7'],['Menta','#DDF1E6'],['Lilás','#E9E2F7'],['Rosa','#F8E1EA'],['Areia','#F3EBDD'],['Cinza','#DADDE3'],
