function hexOk(c){return /^#[0-9a-f]{6}$/i.test(c||'')}
function ehFoto(v){return /^(https:\/\/|data:image\/)/i.test(v||'')}
function luminancia(hex){const n=parseInt(hex.slice(1),16),f=v=>{v/=255;return v<=.03928?v/12.92:Math.pow((v+.055)/1.055,2.4)};return .2126*f(n>>16&255)+.7152*f(n>>8&255)+.0722*f(n&255)}
/** Links do Google Drive viram link direto da imagem. */
function linkImagem(u){u=String(u||'').trim();const m=u.match(/drive\.google\.com\/(?:file\/d\/|open\?id=|uc\?(?:export=\w+&)?id=)([\w-]{20,})/)||u.match(/[?&]id=([\w-]{20,})/);
  return m&&/google\.com/.test(u)?'https://lh3.googleusercontent.com/d/'+m[1]:u}
function fundoPessoal(){const p=lsGet('qd_fundo')||'';return p==='foto'?(lsGet('qd_foto')||''):p}
function aplicarFundo(v){
  if(v===undefined){const p=fundoPessoal();v=p==='padrao'?'':p||(S.cfg&&S.cfg.fundo)||''}
  const r=document.documentElement.style,cl=document.documentElement.classList;
  document.body.style.backgroundImage='';
  if(ehFoto(v)){
    // foto: véu escuro leve por cima para o texto e as colunas continuarem legíveis
    document.body.style.backgroundImage=`linear-gradient(rgba(0,0,0,.22),rgba(0,0,0,.22)),url("${v.replace(/"/g,'%22')}")`;
    r.setProperty('--bg','#2B2F36');r.setProperty('--colbg','color-mix(in srgb,var(--panel) 84%,transparent)');
    r.setProperty('--bgTxt','#F2F4F7');r.setProperty('--bgMuted','rgba(242,244,247,.82)');
    cl.add('fundo-escuro','fundo-foto');return;
  }
  cl.remove('fundo-foto');
  if(!hexOk(v)){['--bg','--colbg','--bgTxt','--bgMuted'].forEach(x=>r.removeProperty(x));cl.remove('fundo-escuro');return}
  const escuro=luminancia(v)<.18;
  r.setProperty('--bg',v);
  r.setProperty('--colbg',`color-mix(in srgb,var(--panel) ${escuro?'86%':'62%'},${v})`);
  r.setProperty('--bgTxt',escuro?'#F2F4F7':'#101828');r.setProperty('--bgMuted',escuro?'rgba(242,244,247,.75)':'#475467');
  cl.toggle('fundo-escuro',escuro);
}
