function lerFotoFundo(inp){
  const f=inp.files&&inp.files[0];if(!f)return;
  if(!/^image\//.test(f.type)){toast('Escolha um arquivo de imagem');return}
  const rd=new FileReader();
  rd.onload=()=>{const img=new Image();img.onload=()=>{
    // reduz para no máx. 1920px de largura e JPEG, para caber no navegador
    const k=Math.min(1,1920/img.width,1200/img.height),cv=document.createElement('canvas');
    cv.width=Math.round(img.width*k);cv.height=Math.round(img.height*k);cv.getContext('2d').drawImage(img,0,0,cv.width,cv.height);
    let q=.82,d=cv.toDataURL('image/jpeg',q);while(d.length>1.8e6&&q>.4){q-=.1;d=cv.toDataURL('image/jpeg',q)}
    escolherFundo(d);toast('Prévia aplicada. Clique em “Só para mim” para salvar.');
  };img.onerror=()=>toast('Não consegui ler essa imagem');img.src=rd.result};
  rd.readAsDataURL(f);
}
